#include <stdio.h> struct graph { int edge_weight,source,destination; }; struct graph node[10],temp; int main(){ int n,i,j; printf("Enter total number of edges in graph : "); scanf("%d",&n); printf("Enter all the edges of the graph along with their weight, source and destination 
"); for(i = 0;i < n;i ++) { printf("Enter the weight of %d edge : ",i + 1); scanf("%d",&node[i].edge_weight); printf("Enter the source of %d edge : ",i + 1); scanf("%d",&node[i].source); printf("Enter the destination of %d edge : ",i + 1); scanf("%d",&node[i].destination); printf("______________________________________
"); } for(i = 0;i < n;i ++) { for(j = i + 1;j < n;j ++) { if(node[i].edge_weight > node[j].edge_weight) { temp = node[i]; node[i] = node[j]; node[j] = temp; } } } for(i = 0;i < n;i ++) { printf("Source : %d	Weight : %d	Destination : %d
",node[i].source,node[i].edge_weight,node[i].destination); } return 0; }
